function login() {
    try {
        var url = source.bookSourceUrl.replace(/\/+$/, '');
        var ur = source.getLoginInfoMap();
        var params = 'username=' + encodeURIComponent(ur.get('账号')) + '&password=' + encodeURIComponent(ur.get('密码'));
        var r = java.post(url + '/login.php', params, {
            'Content-Type': 'application/x-www-form-urlencoded'
        });
        // 检查响应内容是否包含登录成功标志（可根据实际页面调整）
        var body = r.body();
        if (body.indexOf('登录成功') >= 0 || body.indexOf('欢迎') >= 0 || r.statusCode() == 302) {
            var cookies = Array.from(r.cookies(), function(entry) { return entry[0] + '=' + entry[1]; }).join(';');
            return source.putLoginHeader(JSON.stringify({ Cookie: cookies }));
        } else {
            throw new Error('登录失败，请检查账号和密码');
        }
    } catch (e) {
        java.log('登录异常: ' + e.message);
        throw e;
    }
}

